select json_build_object(
  'listed', (select count(*) from v),
  'on_run_before', count(*) filter (where r.extracted_run = v.extracted_run and r.checks->>'arithmetic' = v.arith_before and not (r.checks ? 'gaps')),
  'on_run_has_gaps', count(*) filter (where r.extracted_run = v.extracted_run and r.checks ? 'gaps'),
  'on_run_arith_moved', count(*) filter (where r.extracted_run = v.extracted_run and r.checks->>'arithmetic' is distinct from v.arith_before),
  'off_run', count(*) filter (where r.extracted_run is distinct from v.extracted_run),
  'checked_now', count(*) filter (where r.checked))
  from v join public.program_requirement_records r
    on r.college = v.college and r.control_number = v.control_number;
